@Test
public void testMapper() throws IOException {
    final Mapper<Text, Text, Text, Text> mapper = new CounterMapper();
    final MapDriver<Text, Text, Text, Text> driver = MapDriver.newMapDriver(mapper);
    driver.withInput(new Text("foo"), new Text("bar")).run();
    assertEquals("Expected 1 counter increment", 1, driver.getCounters().findCounter(GROUP, ELEM).getValue());
}

@Test
public void testReducer() throws IOException {
    final Reducer<Text, Text, Text, Text> reducer = new CounterReducer();
    final ReduceDriver<Text, Text, Text, Text> driver = ReduceDriver.newReduceDriver(reducer);
    driver.withInputKey(new Text("foo")).withInputValue(new Text("bar")).run();
    assertEquals("Expected 1 counter increment", 1, driver.getCounters().findCounter(GROUP, ELEM).getValue());
}

@Test
public void testMapReduce() throws IOException {
    final Mapper<Text, Text, Text, Text> mapper = new CounterMapper();
    final Reducer<Text, Text, Text, Text> reducer = new CounterReducer();
    final MapReduceDriver<Text, Text, Text, Text, Text, Text> driver = MapReduceDriver.newMapReduceDriver(mapper, reducer);
    driver.withInput(new Text("foo"), new Text("bar")).run();
    assertEquals("Expected counter=3", 3, driver.getCounters().findCounter(GROUP, ELEM).getValue());
}

